package vn.smartfarm.iot.irrigation;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;import java.time.temporal.ChronoUnit;import java.sql.*;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.annotation.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.server.ResponseStatusException;

/** One explicit, bounded post-OFF CLOSE/FINISH attempt. Never OPEN, ON, OFF, resume or replay. */
@Service
public class SessionClosure {
 public record Arm(UUID armId,long expectedRevision,UUID offId,Instant reviewedAt) {}
 public record Record(UUID sessionId,UUID armId,Arm definition,UUID offId,UUID closeId,UUID finishId,Instant armedAt,Instant deadline,String state,String reason,Instant finishedAt) {}
 public record View(String mode,String circuitId,UUID sessionId,Instant asOf,long sessionRevision,UUID offId,String phase,boolean enabled,boolean canArm,String reason,Record closure) {}
 private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final IrrigationSession sessions;private final TransactionTemplate tx;private final boolean enabled;
 public SessionClosure(JdbcTemplate jdbc,ObjectMapper mapper,IrrigationSession sessions,PlatformTransactionManager manager,@Value("${smartfarm.irrigation.session-closure-enabled:false}")boolean enabled){this.jdbc=jdbc;this.mapper=mapper;this.sessions=sessions;this.enabled=enabled;tx=new TransactionTemplate(manager);}
 private static boolean active(Record r){return Set.of("ARMED","CLOSE_RESERVED","WAIT_CLOSED").contains(r.state());}
 private void gates(){jdbc.queryForObject("SELECT singleton FROM pump_dispatch_gate WHERE singleton=1 FOR UPDATE",Integer.class);jdbc.queryForObject("SELECT revision FROM irrigation_circuit_state WHERE singleton=1 FOR UPDATE",Long.class);}
 private String encode(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){throw new IllegalStateException(e);}}
 private Arm decode(String s){try{return mapper.readValue(s,Arm.class);}catch(Exception e){throw new IllegalStateException("Invalid closure definition",e);}}
 private Record map(ResultSet r,int n)throws SQLException{return new Record(r.getObject("session_id",UUID.class),r.getObject("arm_id",UUID.class),decode(r.getString("definition")),r.getObject("off_id",UUID.class),r.getObject("close_id",UUID.class),r.getObject("finish_id",UUID.class),r.getTimestamp("armed_at").toInstant(),r.getTimestamp("deadline").toInstant(),r.getString("state"),r.getString("reason"),r.getTimestamp("finished_at")==null?null:r.getTimestamp("finished_at").toInstant());}
 private Record find(UUID session){return jdbc.query("SELECT * FROM irrigation_session_closure WHERE session_id=?",this::map,session).stream().findFirst().orElse(null);}
 private boolean binding(IrrigationSession.Run r,IrrigationSession.View v){var i=v.pump().commandFence().intent();return r.config().expectedSource().equals("SIMULATOR")&&r.config().equals(v.valve().config())&&v.valve().latest()!=null&&v.valve().latest().config().equals(r.config())&&v.valve().latest().bootId().equals(r.valveBootId())&&i!=null&&Objects.equals(i.bootId(),r.pumpBootId())&&v.pump().commandFence().required()&&v.pump().commandFence().compatible()&&!v.pump().commandFence().restartRequired()&&v.enabled()&&v.valve().enabled()&&v.pump().controlEnabled()&&v.pump().commandFence().circuitRouteRequired()&&vn.smartfarm.iot.control.PumpCircuitRoute.from(r.config()).equals(v.pump().commandFence().circuitRoute())&&v.valve().configurationState().equals("CURRENT");}
 private String offState(UUID id){return jdbc.query("SELECT state FROM pump_command WHERE command_id=? AND action='OFF'",(r,n)->r.getString(1),id).stream().findFirst().orElse("MISSING");}
 private boolean offAck(IrrigationSession.Run r){return jdbc.queryForObject("SELECT count(*) FROM pump_command WHERE command_id=? AND action='OFF' AND state='EXECUTED' AND reported_state='OFF' AND ack_boot_id=?",Integer.class,r.offId(),r.pumpBootId())==1;}
 private String armReason(IrrigationSession.Run r,IrrigationSession.View v){if(!enabled||!sessions.closureReady())return "PROFILE_DISABLED";if(!r.stopRequested()||r.offId()==null||!r.phase().equals("WAIT_OFF"))return "REQUEST_OFF_FIRST";if(v.active()==null||!v.active().sessionId().equals(r.sessionId())||!binding(r,v))return "BINDING_OR_PROFILE_CHANGED";if(!Set.of("SENT","EXECUTED").contains(offState(r.offId())))return "OFF_OUTCOME_UNRESOLVED";return "READY";}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public View snapshot(String circuit,UUID session){var r=sessions.find(circuit,session);var c=find(session);String reason=c==null?armReason(r,sessions.snapshot(circuit)):c.reason();return new View("POST_OFF_CLOSURE",circuit,session,Instant.now(),r.revision(),r.offId(),r.phase(),enabled,c==null&&reason.equals("READY"),reason,c);}
 public Record arm(String circuit,UUID session,Arm input){if(input==null||input.armId()==null||input.offId()==null||input.reviewedAt()==null||input.expectedRevision()<1||input.expectedRevision()>9007199254740991L)throw bad(HttpStatus.BAD_REQUEST,"Invalid closure arm");var a=new Arm(input.armId(),input.expectedRevision(),input.offId(),input.reviewedAt().truncatedTo(ChronoUnit.MICROS));return tx.execute(t->{gates();var r=sessions.find(circuit,session);var old=find(session);if(old!=null){if(!old.definition().equals(a))throw bad(HttpStatus.CONFLICT,"Closure already has a one-shot definition");return old;}var now=Instant.now().truncatedTo(ChronoUnit.MICROS);if(a.reviewedAt().isBefore(now.minusSeconds(10))||a.reviewedAt().isAfter(now.plusSeconds(2))||r.revision()!=a.expectedRevision()||!a.offId().equals(r.offId())||!armReason(r,sessions.snapshot(circuit)).equals("READY"))throw bad(HttpStatus.CONFLICT,"Review current post-OFF session and boot");jdbc.update("INSERT INTO irrigation_session_closure(session_id,arm_id,definition,off_id,close_id,finish_id,armed_at,deadline,state,reason) VALUES(?,?,?::jsonb,?,?,?,?,?,'ARMED','WAIT_OFF_PROOF')",session,a.armId(),encode(a),r.offId(),UUID.randomUUID(),UUID.randomUUID(),Timestamp.from(now),Timestamp.from(now.plusSeconds(15)));return find(session);});}
 public Record pause(String circuit,UUID session,UUID arm){if(arm==null)throw bad(HttpStatus.BAD_REQUEST,"Arm ID required");return tx.execute(t->{gates();sessions.find(circuit,session);var c=find(session);if(c==null||!c.armId().equals(arm))throw bad(HttpStatus.NOT_FOUND,"Closure not found");end(c,"PAUSED","OPERATOR_PAUSED",false);return find(session);});}
 private void end(Record c,String state,String reason,boolean recover){if(!active(c))return;jdbc.update("UPDATE irrigation_session_closure SET state=?,reason=?,finished_at=CURRENT_TIMESTAMP WHERE session_id=? AND state IN ('ARMED','CLOSE_RESERVED','WAIT_CLOSED')",state,reason,c.sessionId());if(recover)jdbc.update("UPDATE irrigation_session SET phase='RECOVERY_REQUIRED',stop_requested=true,reason=?,revision=revision+1 WHERE session_id=? AND phase<>'CLOSED_CONFIRMED'","AUTO_CLOSURE_"+reason,c.sessionId());}
 private Record checked(String circuit,Record expected,String state){var c=find(expected.sessionId());var r=sessions.find(circuit,expected.sessionId());if(c==null||!c.armId().equals(expected.armId())||!c.state().equals(state)||!c.deadline().isAfter(Instant.now())||!Objects.equals(r.offId(),c.offId())||!binding(r,sessions.snapshot(circuit)))throw bad(HttpStatus.CONFLICT,"Closure superseded or expired; never replay");return c;}
 public void poll(){if(!enabled||!sessions.closureReady())return;var candidates=jdbc.query("SELECT c.* FROM irrigation_session_closure c WHERE state IN ('ARMED','CLOSE_RESERVED','WAIT_CLOSED')",this::map);for(var expected:candidates)advance(expected);}
 private void advance(Record expected){var step=tx.execute(t->{gates();var c=find(expected.sessionId());if(c==null||!active(c)||!c.armId().equals(expected.armId()))return null;String circuit=jdbc.queryForObject("SELECT circuit_id FROM irrigation_session WHERE session_id=?",String.class,c.sessionId());var r=sessions.find(circuit,c.sessionId());
  if(!Objects.equals(r.offId(),c.offId())||!Set.of("WAIT_OFF","DISPATCHING_CLOSE","WAIT_CLOSED").contains(r.phase())){end(c,"INTERRUPTED","SESSION_CHANGED",false);return null;}
  if(!c.deadline().isAfter(Instant.now())){end(c,"EXPIRED","DEADLINE_REACHED",true);return null;}
  var v=sessions.snapshot(circuit);if(!binding(r,v)){end(c,"INTERRUPTED","BINDING_OR_PROFILE_CHANGED",true);return null;}
  if(!Set.of("SENT","EXECUTED").contains(offState(c.offId()))){end(c,"UNRESOLVED","OFF_OUTCOME_UNRESOLVED",true);return null;}
  if(c.state().equals("CLOSE_RESERVED"))return null; // another evaluator is dispatching; no replay
  if(c.state().equals("WAIT_CLOSED")){var ops=jdbc.queryForList("SELECT state FROM irrigation_session_action WHERE request_id=?",String.class,c.closeId());var commands=jdbc.queryForList("SELECT state FROM circuit_demo_command WHERE command_id=?",String.class,c.closeId());if(ops.isEmpty()||!ops.getFirst().equals("RETURNED")||commands.isEmpty()||!Set.of("SENT","EXECUTED").contains(commands.getFirst())){end(c,"UNRESOLVED","CLOSE_OUTCOME_UNRESOLVED",true);return null;}}
  String action=c.state().equals("ARMED")&&v.canClose()&&offAck(r)?"CLOSE":c.state().equals("WAIT_CLOSED")&&v.canFinish()&&offAck(r)?"FINISH":null;
  return action==null?null:new Step(c,circuit,r.revision(),action);
 });if(step==null)return;var c=step.closure();String action=step.action();UUID id=action.equals("CLOSE")?c.closeId():c.finishId();
 try{var receipt=sessions.actForClosure(step.circuit(),c.sessionId(),new IrrigationSession.Action(id,action,step.revision(),Instant.now()),()->{checked(step.circuit(),c,action.equals("CLOSE")?"ARMED":"WAIT_CLOSED");if(!offAck(sessions.find(step.circuit(),c.sessionId())))throw bad(HttpStatus.CONFLICT,"OFF ACK missing");jdbc.update("UPDATE irrigation_session_closure SET state=?,reason=?,finished_at=? WHERE session_id=?",action.equals("CLOSE")?"CLOSE_RESERVED":"COMPLETE",action.equals("CLOSE")?"WAIT_CLOSE_RESULT":"OFF_AND_CLOSED_CONFIRMED",action.equals("CLOSE")?null:Timestamp.from(Instant.now()),c.sessionId());},()->{checked(step.circuit(),c,"CLOSE_RESERVED");if(jdbc.queryForObject("SELECT count(*) FROM irrigation_session WHERE session_id=? AND close_id=? AND phase='DISPATCHING_CLOSE' AND off_id=?",Integer.class,c.sessionId(),c.closeId(),c.offId())!=1)throw bad(HttpStatus.CONFLICT,"Close superseded");});
  if(action.equals("CLOSE"))tx.executeWithoutResult(t->{gates();var current=find(c.sessionId());if(current!=null&&current.state().equals("CLOSE_RESERVED")){if(receipt.operation().state().equals("RETURNED"))jdbc.update("UPDATE irrigation_session_closure SET state='WAIT_CLOSED',reason='WAIT_CLOSED_PROOF' WHERE session_id=?",c.sessionId());else end(current,"UNRESOLVED","CLOSE_OUTCOME_UNRESOLVED",true);}});
 }catch(ResponseStatusException ignored){/* Re-evaluate only if no action was reserved; never replay a committed identity. */}
 }
 private record Step(Record closure,String circuit,long revision,String action) {}
 private static ResponseStatusException bad(HttpStatus s,String m){return new ResponseStatusException(s,m);}
}
